INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@rrb_exam, 18, 'General Intelligence & Reasoning', 'Syllogism', 'Medium', 'Statements: All pens are pencils. All pencils are erasers. Conclusions: I. All pens are erasers. II. Some erasers are pens. Which conclusion(s) follow?', 0, NULL, 'From "All pens are pencils" and "All pencils are erasers", by transitivity all pens are erasers (I), and since all pens are erasers, some erasers are definitely pens (II).', 'C');
